// per (owner_id, pathname, search) — see migration add_saved_views_owner_path_unique.\n  /// Partial unique `saved_views_owner_chart_resource_active_key` — one active chart\n  /// bookmark per owner per resource_id — see add_saved_views_resource_kind.\n\n  @@index([owner_id, status])\n  @@index([owner_id, status, resource_kind])\n  @@index([project_id])\n}\n\nmodel saved_view_shares {\n  id         String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  view_id    String       @db.Uuid\n  user_id    String       @db.Uuid\n  status     RecordStatus @default(active)\n  created_by String?      @db.Uuid\n  created_at DateTime     @default(now()) @db.Timestamptz(6)\n  updated_by String?      @db.Uuid\n  updated_at DateTime     @updatedAt @db.Timestamptz(6)\n\n  view            saved_views @relation(fields: [view_id], references: [id], onDelete: Cascade)\n  user            users       @relation(\"SavedViewShareRecipient\", fields: [user_id], references: [id], onDelete: Cascade)\n  created_by_user users?      @relation(\"SavedViewShareCreatedBy\", fields: [created_by], references: [id], onDelete: SetNull)\n  updated_by_user users?      @relation(\"SavedViewShareUpdatedBy\", fields: [updated_by], references: [id], onDelete: SetNull)\n\n  @@unique([view_id, user_id])\n  @@index([user_id, status])\n}\n\n/// Per-user chart workspace (board JSON: widgets + layout).\nmodel charts {\n  id          String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  owner_id    String       @db.Uuid\n  title       String\n  description String?\n  board_json  Json         @default(\"{}\")\n  is_overview Boolean      @default(false)\n  status      RecordStatus @default(active)\n  created_by  String?      @db.Uuid\n  created_at  DateTime     @default(now()) @db.Timestamptz(6)\n  updated_by  String?      @db.Uuid\n  updated_at  DateTime     @updatedAt @db.Timestamptz(6)\n\n  owner           users          @relation(\"ChartOwner\", fields: [owner_id], references: [id], onDelete: Cascade)\n  created_by_user users?         @relation(\"ChartCreatedBy\", fields: [created_by], references: [id], onDelete: SetNull)\n  updated_by_user users?         @relation(\"ChartUpdatedBy\", fields: [updated_by], references: [id], onDelete: SetNull)\n  shares          chart_shares[]\n  saved_views     saved_views[]  @relation(\"ChartSavedViewBookmark\")\n\n  @@index([owner_id, status])\n}\n\nmodel chart_shares {\n  id         String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  chart_id   String       @db.Uuid\n  user_id    String       @db.Uuid\n  status     RecordStatus @default(active)\n  created_by String?      @db.Uuid\n  created_at DateTime     @default(now()) @db.Timestamptz(6)\n  updated_by String?      @db.Uuid\n  updated_at DateTime     @updatedAt @db.Timestamptz(6)\n\n  chart           charts @relation(fields: [chart_id], references: [id], onDelete: Cascade)\n  user            users  @relation(\"ChartShareRecipient\", fields: [user_id], references: [id], onDelete: Cascade)\n  created_by_user users? @relation(\"ChartShareCreatedBy\", fields: [created_by], references: [id], onDelete: SetNull)\n  updated_by_user users? @relation(\"ChartShareUpdatedBy\", fields: [updated_by], references: [id], onDelete: SetNull)\n\n  @@unique([chart_id, user_id])\n  @@index([user_id, status])\n}\n\nmodel github_pull_requests {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  work_item_id String   @db.Uuid\n  pr_number    Int\n  repo_owner   String\n  repo_name    String\n  pr_title     String\n  pr_url       String\n  branch_name  String?\n  status       String?\n  created_at   DateTime @default(now()) @db.Timestamptz(6)\n  updated_at   DateTime @updatedAt @db.Timestamptz(6)\n\n  work_item work_items @relation(fields: [work_item_id], references: [id], onDelete: Cascade)\n\n  @@unique([work_item_id, repo_owner, repo_name, pr_number])\n}\n\n/// Workspace-level integration instance (chat models, Slack, Figma, etc.).\n/// Secrets live encrypted inside `config` JSONB; API access is service-role only.\nmodel integrations {\n  id         String              @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  /// Static catalog id, e.g. \"alice-gemini\", \"openai\", \"slack\".\n  catalog_id String\n  category   IntegrationCategory\n  /// Provider slug for strategy dispatch: gemini, openai, anthropic, slack, …\n  provider   String\n  /// Admin-facing label, e.g. \"Gemini 3.6\", \"GPT-4o (production)\".\n  name       String\n  status     IntegrationStatus   @default(draft)\n  /// Provider-specific JSON; secret fields stored as v1:… ciphertext.\n  config     Json                @default(\"{}\")\n  /// Default Alice Chat model when user has not picked one (ai_agent only).\n  is_default Boolean             @default(false)\n  sort_order Int                 @default(0)\n  created_by String?             @db.Uuid\n  created_at DateTime            @default(now()) @db.Timestamptz(6)\n  updated_by String?             @db.Uuid\n  updated_at DateTime            @updatedAt @db.Timestamptz(6)\n\n  created_by_user users? @relation(\"IntegrationCreatedBy\", fields: [created_by], references: [id], onDelete: SetNull)\n  updated_by_user users? @relation(\"IntegrationUpdatedBy\", fields: [updated_by], references: [id], onDelete: SetNull)\n\n  @@index([category, status])\n  @@index([catalog_id])\n  @@index([provider, status])\n}\n",
